mapper.insert:
insert into coach_provide (
coach_idx, minor_field_idx) values (
#{coach_idx}, #{myMinorCate}
)

insert into coach_interest (
coach_idx, minor_field_idx) values (
#{coach_idx}, #{interMinorCate}
)

insert into coach_region (
coach_idx, major_region_idx, minor_region_idx) values (
#{coach_idx}, #{myMajorRegion}, #{myMinorRegion}
)

INSERT INTO hashtag (hashtag_idx, tags) SELECT seq_hashtag.nextval, tags FROM (
SELECT #{tag} AS tags FROM DUAL
)
